import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int bp;

    static String next() {
        while (buf[bp] <= ' ') bp++;
        int s = bp;
        while (bp < buf.length && buf[bp] > ' ') bp++;
        return new String(buf, s, bp - s);
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        long window = Long.parseLong(next()), limit = Long.parseLong(next());
        int q = Integer.parseInt(next());
        // Fixed windows: quota is counted per (key, floor(timestamp / window)).
        HashMap<String, Long> counts = new HashMap<>(4 * q);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < q; i++) {
            long ts = Long.parseLong(next());
            String k = next() + "#" + (ts / window);
            long c = counts.getOrDefault(k, 0L);
            if (i > 0) sb.append(' ');
            if (c < limit) { counts.put(k, c + 1); sb.append("ALLOW"); }
            else sb.append("REJECT");
        }
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	next := func() string { sc.Scan(); return sc.Text() }
	num := func() int64 { v, _ := strconv.ParseInt(next(), 10, 64); return v }
	window, limit, q := num(), num(), int(num())
	// Fixed windows: quota is counted per (key, floor(timestamp / window)).
	type bucket struct {
		key string
		id  int64
	}
	counts := make(map[bucket]int64, q)
	w := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer w.Flush()
	for i := 0; i < q; i++ {
		ts := num()
		b := bucket{next(), ts / window}
		if i > 0 {
			w.WriteByte(' ')
		}
		if counts[b] < limit {
			counts[b]++
			w.WriteString("ALLOW")
		} else {
			w.WriteString("REJECT")
		}
	}
	w.WriteByte('\n')
}
